package app.noir.mobile;
import android.app.AlertDialog;
import org.json.JSONObject;
import android.content.Intent;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;

final class PhoneExperience {
 static final String BUILD="Standalone · 2026-10-25";
 static String version(android.content.Context c){try{return "Noir for Android "+c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName+" · "+BUILD;}catch(Exception e){return "Noir for Android · "+BUILD;}}
 static boolean trackerOnly(DataStore data){return data.playbackFlag("historyOnly",false);}
 static void choose(MainActivity a,boolean track){a.data.phoneSetting("historyOnly",track);a.data.pref("experienceChosen",true);a.page=track?"History":"Home";a.detail="";a.premium.historyView="Up next";a.render();}
 static void welcome(MainActivity a){a.heading("Your cinema, on your phone.");a.paragraph("Your history, your lists, your next episode. Make Noir yours.");a.body.addView(a.button("Just track what I watch",()->choose(a,true),true));a.paragraph("Watch anywhere. Log here. Keep your viewing story with you.");a.body.addView(a.button("Watch & track",()->{choose(a,false);a.startActivity(new Intent(a,DiscoverActivity.class));},false));a.body.addView(a.button("Import history or restore a backup",()->a.startActivity(new Intent(a,HistoryToolsActivity.class)),false));}
 static View profileHeader(MainActivity a){JSONObject me;try{me=a.data.profiles.get(a.data.profileId);}catch(RuntimeException e){me=new JSONObject();}String name=me.optString("name").trim();int color=MainActivity.GOLD;try{color=android.graphics.Color.parseColor(me.optString("color","#E5C185"));}catch(RuntimeException ignored){}if(name.isEmpty())name=a.data.prefs().optString("displayName",a.browsingSettings().optString("profileName",Loc.t("You"))).trim();if(name.isEmpty())name=Loc.t("You");LinearLayout card=new LinearLayout(a);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(a.dp(18),a.dp(PhoneDensity.pick(14,20)),a.dp(18),a.dp(PhoneDensity.pick(14,20)));card.setBackground(MainActivity.bg(0xff241f19,a.dp(22)));TextView avatar=a.text(name.substring(0,name.offsetByCodePoints(0,1)).toUpperCase(java.util.Locale.getDefault()),PhoneDensity.pick(22,25),MainActivity.BLACK);avatar.setTypeface(null,Typeface.BOLD);avatar.setGravity(Gravity.CENTER);avatar.setBackground(MainActivity.bg(color,a.dp(30)));card.addView(avatar,new LinearLayout.LayoutParams(a.dp(PhoneDensity.pick(52,60)),a.dp(PhoneDensity.pick(52,60))));LinearLayout info=a.column();info.setPadding(a.dp(16),0,a.dp(10),0);TextView title=a.text(name,PhoneDensity.pick(21,24),MainActivity.WHITE);title.setTypeface(null,Typeface.BOLD);info.addView(title);info.addView(a.text(me.optString("pcProfileName").isEmpty()?Loc.t("Only on this phone · tap to switch or add profiles"):Loc.f("Linked to %s on your PC · tap to manage",me.optString("pcProfileName")),12,MainActivity.MUTED));card.addView(info,new LinearLayout.LayoutParams(0,-2,1));card.addView(a.text("›",24,MainActivity.GOLD));card.setContentDescription(Loc.t("Profile"));card.setOnClickListener(v->onProfileTap(a));Motion.card(card);return card;}
 static void onProfileTap(MainActivity a){a.startActivity(new android.content.Intent(a,ProfilesActivity.class));}
 static void settings(MainActivity a){PhoneTips.init();a.heading("Your space");a.body.addView(profileHeader(a));a.heading("The way you watch");
  row(a,"◉","Experience",trackerOnly(a.data)?"Just track what I watch":"Watch & track",()->{NoirSheet s=new NoirSheet(a,"Experience",null);s.choice("Just track what I watch",null,trackerOnly(a.data),()->choose(a,true));s.choice("Watch & track",null,!trackerOnly(a.data),()->choose(a,false));s.show();});
  row(a,"▶","Playback","Autoplay, intros and credits",()->playback(a));a.body.addView(PhonePreview.settingsRow(a));row(a,"≡","Subtitles",Loc.t(a.data.defaultSubtitleLanguage())+" · "+Loc.t("Default language and where subtitles come from"),()->subtitles(a));
  if(!trackerOnly(a.data)){row(a,"↓","Downloads","Saved videos on this phone",()->a.startActivity(new Intent(a,DownloadHubActivity.class)));a.body.addView(DownloadHubActivity.pickupRow(a));row(a,"⌁","Streaming","Your AIOStreams connection",()->a.startActivity(new Intent(a,PhoneDownloadSettingsActivity.class)));}
  a.heading("Your library & history");row(a,"◷","History tools","Import, export and backup here",()->a.startActivity(new Intent(a,HistoryToolsActivity.class)));row(a,"♡",TasteActivity.label(),"Swap a code with a friend and see what you both love",()->TasteActivity.open(a));a.body.addView(PhoneCatchUp.settingsRow(a));boolean alerts=a.data.prefs().optBoolean("alerts",true);row(a,"🔔","New-episode alerts",alerts?"On · a notification when a show you follow airs":"Off · no notifications for new episodes",()->{a.data.pref("alerts",!alerts);if(!alerts)EpisodeAlerts.askPermission(a);a.renderKeep();});row(a,"⇄","Connections","History services and sync",()->{a.page="Connections";a.render();});row(a,"▣","Your PC",!a.data.problemLine().isEmpty()?a.data.problemLine():a.data.paired()?(a.data.online?"Connected · synced":"PC paired · sync pending"):"Optional sync with Windows",()->pc(a));
  if(a.data.paired())BackgroundSync.settings(a);a.heading("Make it yours");row(a,"ع","Language",Loc.arabic?"العربية":"English",()->{NoirSheet s=new NoirSheet(a,"Language",null);s.choice("English",null,!Loc.arabic,()->a.setLanguage("en"));s.choice("العربية",null,Loc.arabic,()->a.setLanguage("ar"));s.show();});row(a,"▤","Size",PhoneDensity.compact?"Compact":"Comfortable",()->size(a));row(a,"✦","Tips & shortcuts","Everything Noir can do, in one place",()->PhoneTips.list(a));row(a,"ⓘ","About","Noir for Android",()->new AlertDialog.Builder(a).setTitle(Loc.t("About")).setMessage(version(a)+"\n\n"+Loc.t("Metadata: Cinemeta and TVmaze. Playback: VideoLAN LibVLC. Artwork belongs to its owners.")).setPositiveButton(Loc.t("OK"),null).show());
 }
 static void row(MainActivity a,String icon,String title,String subtitle,Runnable act){a.body.addView(rowView(a,icon,title,subtitle,act));}
 static View rowView(MainActivity a,String icon,String title,String subtitle,Runnable act){LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(a.dp(14),a.dp(PhoneDensity.pick(10,13)),a.dp(14),a.dp(PhoneDensity.pick(10,13)));row.setBackground(MainActivity.bg(MainActivity.PANEL,a.dp(14)));TextView glyph=a.text(icon,PhoneDensity.pick(19,21),MainActivity.GOLD);glyph.setGravity(Gravity.CENTER);row.addView(glyph,new LinearLayout.LayoutParams(a.dp(34),a.dp(36)));LinearLayout info=a.column();info.setPadding(a.dp(12),0,a.dp(8),0);TextView name=a.text(title,PhoneDensity.cardTitle(),MainActivity.WHITE);name.setTypeface(null,Typeface.BOLD);info.addView(name);info.addView(a.text(subtitle,PhoneDensity.pick(11,11),MainActivity.MUTED));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.addView(a.text("›",20,MainActivity.MUTED));row.setOnClickListener(v->act.run());row.setContentDescription(Loc.t(title));Motion.card(row);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,a.dp(6));row.setLayoutParams(p);return row;}
 static void size(MainActivity a){NoirSheet s=new NoirSheet(a,"Size",null);s.choice("Compact","Smaller text and cards, more on screen",PhoneDensity.compact,()->{PhoneDensity.set(a,true);a.render();});s.choice("Comfortable","Larger text and cards",!PhoneDensity.compact,()->{PhoneDensity.set(a,false);a.render();});s.show();}
 static void playback(MainActivity a){PlayerPrefs.settings(a,a.data);}
 static String[] localized(String[] values){String[] result=values.clone();for(int n=0;n<result.length;n++)result[n]=Loc.t(result[n]);return result;}
 static void subtitles(MainActivity a){String[] values={"English","Arabic","Off"};NoirSheet s=new NoirSheet(a,"Subtitles",null);for(String value:values)s.choice(value,null,value.equals(a.data.defaultSubtitleLanguage()),()->a.data.phoneSetting("subtitles",value));s.link("Subtitle source",true,true,()->a.startActivity(new android.content.Intent(a,PhoneDownloadSettingsActivity.class)));s.show();}
 static void pc(MainActivity a){String[] options=a.data.paired()?new String[]{"Sync now","Pair again / update PC address","Downloads on my PC"}:new String[]{"Pair with my PC"};NoirSheet s=new NoirSheet(a,"Your PC",null);String[] icons=a.data.paired()?new String[]{"⟳","⇄","↓"}:new String[]{"⇄"};for(int k=0;k<options.length;k++){final int n=k;s.action(icons[k],options[k],null,()->{if(!a.data.paired()||n==1)a.pairInput();else if(n==0)a.sync(true);else a.startActivity(new Intent(a,PcDownloadsActivity.class));});}s.show();}
}
